#pragma once

// =============================================================================
// config_defaults.h -- Default values for all ENABLE_* flags
//
// These are the fallback values used when the flag has not been defined by:
//   - user_config.h STEP 2 (user preferences)
//   - Board hardware defaults
//
// Included by user_config.h before packs, so packs can override with plain
// #undef / #define without #ifdef guards.
//
// !!!  DO NOT EDIT THIS FILE directly.  Change values in user_config.h STEP 2
//      or in the relevant packs/pack_*.h file.
// =============================================================================

